export const teamsAddMember = <ThrowOnError extends boolean = false>(options: Options<TeamsAddMemberData, ThrowOnError>): RequestResult<TeamsAddMemberResponses, TeamsAddMemberErrors, ThrowOnError> => (options.client ?? client).post<TeamsAddMemberResponses, TeamsAddMemberErrors, ThrowOnError>({
    responseType: 'json',
    url: '/teams/{team_uuid}/characters/{character_slug}',
    ...options
});

